import { constants } from "node:fs";
import { open, lstat, readdir, realpath } from "node:fs/promises";
import { createHash } from "node:crypto";
import path from "node:path";

const DEFAULT_IGNORED = new Set([
  ".git",
  "node_modules",
  "dist",
  "target",
  "target-codex",
  "gen",
  "autogenerated",
  ".cache",
  ".turbo",
  "coverage",
  "generated",
  // Build output and platform caches: big, generated, and never where a task lives.
  "out",
  ".next",
  ".nuxt",
  ".wrangler",
  ".gradle",
  "Pods",
  ".vite",
]);
// Notes, audits and agent scratch folders at the top of a repo. They are scanned after the code,
// so a repo with 10,000+ files of docs cannot use up the file budget before src/ is reached.
const LOW_PRIORITY_TOP = new Set(["docs", "doc", "audit", "audits", "artifacts", "archive", "proof", ".agents", ".claude", ".codex", ".cursor", ".gemini", ".grok", ".sisyphus", ".ledger"]);
const DEFAULT_EXTENSIONS = new Set([
  ".md",
  ".txt",
  ".json",
  ".yaml",
  ".yml",
  ".js",
  ".jsx",
  ".ts",
  ".tsx",
  ".mjs",
  ".cjs",
  ".css",
  ".html",
  ".rs",
  ".toml",
  ".lock",
]);

export const MCP_OPERATION_LIMITS = Object.freeze({
  maxDurationMs: 30_000,
  defaultDurationMs: 20_000,
  maxAggregateBytes: 128 * 1024 * 1024,
  defaultAggregateBytes: 128 * 1024 * 1024,
  maxFileBytes: 2_000_000,
  maxFiles: 10_000,
  maxDirectories: 10_000,
  maxEntries: 50_000,
  maxDepth: 64,
  maxPathCharacters: 4_096,
});

const slash = (value) => value.split(path.sep).join("/");
const sha256 = (value) => createHash("sha256").update(value).digest("hex");

function boundedInteger(value, fallback, minimum, maximum) {
  const number = Number(value ?? fallback);
  if (!Number.isSafeInteger(number)) return fallback;
  return Math.min(maximum, Math.max(minimum, number));
}

function operationError(code, message, cause) {
  const error = new Error(message, cause ? { cause } : undefined);
  error.code = code;
  return error;
}

function abortError(signal) {
  if (signal?.reason?.code === "MCP_OPERATION_TIMEOUT") return signal.reason;
  return operationError("MCP_OPERATION_CANCELLED", "MCP operation was cancelled.", signal?.reason);
}

function entryKind(entry) {
  if (entry.isDirectory()) return "directory";
  if (entry.isFile()) return "file";
  if (entry.isSymbolicLink()) return "symlink";
  return "other";
}

function metadataStamp(stats) {
  return Object.freeze({
    dev: String(stats.dev),
    ino: String(stats.ino),
    size: stats.size,
    mtimeNs: stats.mtimeNs === undefined ? String(stats.mtimeMs) : String(stats.mtimeNs),
    ctimeNs: stats.ctimeNs === undefined ? String(stats.ctimeMs) : String(stats.ctimeNs),
    kind: stats.isDirectory() ? "directory" : stats.isFile() ? "file" : stats.isSymbolicLink() ? "symlink" : "other",
  });
}

function sameStamp(left, right) {
  return left.dev === right.dev
    && left.ino === right.ino
    && left.size === right.size
    && left.mtimeNs === right.mtimeNs
    && left.ctimeNs === right.ctimeNs
    && left.kind === right.kind;
}

function sameEntries(left, right) {
  if (left.length !== right.length) return false;
  return left.every((entry, index) => entry === right[index]);
}

function categoryFor(relativePath, extension) {
  if ([".githooks/pre-commit", ".githooks/pre-push"].includes(relativePath)) return "configuration";
  const lower = relativePath.toLowerCase();
  if (/(^|\/)tests?\//.test(lower) || /\.test\.[^.]+$/.test(lower)) return "test";
  if (extension === ".md" || extension === ".txt") return "document";
  if ([".json", ".yaml", ".yml", ".toml", ".lock"].includes(extension)) return "configuration";
  if ([".css", ".html", ".jsx", ".tsx"].includes(extension)) return "interface";
  return "source";
}

export function createMcpOperation(options = {}) {
  const timeoutMs = boundedInteger(
    options.timeoutMs,
    MCP_OPERATION_LIMITS.defaultDurationMs,
    1,
    MCP_OPERATION_LIMITS.maxDurationMs,
  );
  const maxAggregateBytes = boundedInteger(
    options.maxTotalBytes,
    MCP_OPERATION_LIMITS.defaultAggregateBytes,
    1,
    MCP_OPERATION_LIMITS.maxAggregateBytes,
  );
  const controller = new AbortController();
  const externalSignal = options.signal;
  let consumedBytes = 0;
  let closed = false;
  let externalAbort = null;

  const timer = setTimeout(() => {
    controller.abort(operationError(
      "MCP_OPERATION_TIMEOUT",
      `MCP operation exceeded the ${timeoutMs} ms time limit.`,
    ));
  }, timeoutMs);
  timer.unref?.();

  if (externalSignal) {
    externalAbort = () => controller.abort(abortError(externalSignal));
    if (externalSignal.aborted) externalAbort();
    else externalSignal.addEventListener("abort", externalAbort, { once: true });
  }

  const check = () => {
    if (controller.signal.aborted) throw abortError(controller.signal);
  };

  const consume = (bytes, label = "workspace data") => {
    check();
    if (!Number.isSafeInteger(bytes) || bytes < 0) {
      throw operationError("MCP_OPERATION_INVALID_SIZE", `Invalid byte size reported for ${label}.`);
    }
    if (consumedBytes + bytes > maxAggregateBytes) {
      throw operationError(
        "MCP_OPERATION_BYTE_LIMIT",
        `MCP operation exceeded the ${maxAggregateBytes} byte aggregate read limit.`,
      );
    }
    consumedBytes += bytes;
  };

  const progress = async (event) => {
    check();
    if (typeof options.onProgress !== "function") return;
    await new Promise((resolve, reject) => {
      const onAbort = () => {
        controller.signal.removeEventListener("abort", onAbort);
        reject(abortError(controller.signal));
      };
      controller.signal.addEventListener("abort", onAbort, { once: true });
      Promise.resolve()
        .then(() => options.onProgress(Object.freeze({ ...event, consumedBytes, maxAggregateBytes })))
        .then(
          (value) => {
            controller.signal.removeEventListener("abort", onAbort);
            resolve(value);
          },
          (error) => {
            controller.signal.removeEventListener("abort", onAbort);
            reject(error);
          },
        );
    });
    check();
  };

  return Object.freeze({
    signal: controller.signal,
    maxAggregateBytes,
    check,
    consume,
    progress,
    get consumedBytes() { return consumedBytes; },
    close() {
      if (closed) return;
      closed = true;
      clearTimeout(timer);
      if (externalSignal && externalAbort) externalSignal.removeEventListener("abort", externalAbort);
    },
  });
}

export async function runBoundedMcpOperation(options, task) {
  const operation = createMcpOperation(options);
  try {
    operation.check();
    return await task(operation);
  } finally {
    operation.close();
  }
}

export async function readOpenRegularFile(absolutePath, expectedStats, operation, label) {
  operation.check();
  const noFollow = Number(constants.O_NOFOLLOW ?? 0);
  let handle;
  try {
    handle = await open(absolutePath, Number(constants.O_RDONLY) | noFollow);
  } catch (error) {
    throw operationError("MCP_FILE_OPEN_FAILED", `Could not safely open ${label}.`, error);
  }
  try {
    const openedStats = await handle.stat({ bigint: false });
    const expectedStamp = metadataStamp(expectedStats);
    const openedStamp = metadataStamp(openedStats);
    if (!openedStats.isFile() || !sameStamp(expectedStamp, openedStamp)) {
      throw operationError("MCP_WORKSPACE_CHANGED", `${label} changed while it was being opened.`);
    }
    operation.consume(openedStats.size, label);
    let bytes;
    try {
      bytes = await handle.readFile({ signal: operation.signal });
    } catch (error) {
      if (operation.signal.aborted) throw abortError(operation.signal);
      throw operationError("MCP_FILE_READ_FAILED", `Could not read ${label}.`, error);
    }
    operation.check();
    const afterStats = await handle.stat({ bigint: false });
    if (bytes.length !== openedStats.size || !sameStamp(openedStamp, metadataStamp(afterStats))) {
      throw operationError("MCP_WORKSPACE_CHANGED", `${label} changed while it was being read.`);
    }
    return bytes;
  } finally {
    await handle.close();
  }
}

async function directoryEntries(directory, operation) {
  operation.check();
  const entries = await readdir(directory, { withFileTypes: true });
  operation.check();
  return entries
    .map((entry) => `${entry.name}\u0000${entryKind(entry)}`)
    .sort((left, right) => left.localeCompare(right));
}

function assertRelativePath(root, absolutePath) {
  const relative = slash(path.relative(root, absolutePath));
  if (!relative || relative.startsWith("../") || path.isAbsolute(relative)) {
    throw operationError("MCP_PATH_ESCAPE", "A workspace entry escaped the registered root.");
  }
  if (relative.length > MCP_OPERATION_LIMITS.maxPathCharacters || /[\u0000-\u001f\u007f]/.test(relative)) {
    throw operationError("MCP_PATH_LIMIT", "A workspace path exceeded the safe path boundary.");
  }
  return relative;
}

function partialNotice(reason, scannedFiles, seenFiles, walkComplete, limits) {
  const limit = { files: limits.maxFiles, entries: limits.maxEntries, directories: limits.maxDirectories, depth: limits.maxDepth, bytes: limits.bytes }[reason];
  const of = walkComplete ? `${seenFiles}` : `at least ${seenFiles}`;
  const what = {
    files: `${limit}-file limit`,
    entries: `${limit}-entry limit`,
    directories: `${limit}-folder limit`,
    depth: `${limit}-level folder depth limit`,
    bytes: `${Math.round(limit / (1024 * 1024))} MB read budget`,
  }[reason];
  return Object.freeze({
    reason,
    limit,
    scannedFiles,
    seenFiles,
    walkComplete,
    notice: `Scanned ${scannedFiles} of ${of} files; stopped at the ${what}. Pick a subfolder to cover the rest.`,
  });
}

export async function scanWorkspaceSnapshot(rootPath, options, operation) {
  const root = path.resolve(rootPath);
  const maxFiles = boundedInteger(options?.maxFiles, MCP_OPERATION_LIMITS.maxFiles, 1, MCP_OPERATION_LIMITS.maxFiles);
  const maxFileBytes = boundedInteger(options?.maxFileBytes, MCP_OPERATION_LIMITS.maxFileBytes, 1, MCP_OPERATION_LIMITS.maxFileBytes);
  const maxDirectories = boundedInteger(options?.maxDirectories, MCP_OPERATION_LIMITS.maxDirectories, 1, MCP_OPERATION_LIMITS.maxDirectories);
  const maxEntries = boundedInteger(options?.maxEntries, MCP_OPERATION_LIMITS.maxEntries, 1, MCP_OPERATION_LIMITS.maxEntries);
  const maxDepth = boundedInteger(options?.maxScanDepth, MCP_OPERATION_LIMITS.maxDepth, 1, MCP_OPERATION_LIMITS.maxDepth);
  const ignored = new Set(options?.ignored ?? DEFAULT_IGNORED);
  const extensions = new Set(options?.extensions ?? DEFAULT_EXTENSIONS);
  const retainContent = options?.retainContent === true;
  // allowPartial: on a repo past a ceiling, keep what was read and say how much
  // was left out instead of refusing the whole scan. Every bound still holds:
  // nothing past maxFiles is read, and walking stops at the entry or
  // directory ceiling.
  const allowPartial = options?.allowPartial === true;
  let truncated = null;
  let eligibleFiles = 0;
  let walkComplete = true;
  // Bytes still owed to the re-read pass below, so a partial scan stops
  // reading while the whole operation can still finish inside its budget.
  let pendingVerifyBytes = 0;
  const partialReserveBytes = Math.min(1024 * 1024, Math.floor(operation.maxAggregateBytes / 8));
  const contentByPath = retainContent ? new Map() : null;
  const files = [];
  const skipped = [];
  const directorySnapshots = [];
  const fileSnapshots = [];
  const queue = [{ absolutePath: root, depth: 0, low: false }];
  const lowQueue = [];
  let visitedEntries = 0;

  const rootStats = await lstat(root, { bigint: false });
  if (rootStats.isSymbolicLink() || !rootStats.isDirectory()) {
    throw operationError("MCP_WORKSPACE_ROOT_REFUSED", "Registered workspace root is not a regular directory.");
  }
  const rootRealPath = await realpath(root);
  operation.check();

  walk: while (queue.length || lowQueue.length) {
    if (!queue.length) queue.push(...lowQueue.splice(0));
    if (directorySnapshots.length >= maxDirectories) {
      if (allowPartial) {
        truncated ??= "directories";
        walkComplete = false;
        break;
      }
      throw operationError("MCP_DIRECTORY_LIMIT", `Workspace scan exceeded ${maxDirectories} directories.`);
    }
    const current = queue.shift();
    const relativeDirectory = current.depth === 0 ? "" : assertRelativePath(root, current.absolutePath);
    const before = await lstat(current.absolutePath, { bigint: false });
    if (before.isSymbolicLink() || !before.isDirectory()) {
      throw operationError("MCP_WORKSPACE_CHANGED", `Directory ${relativeDirectory || "."} changed during the scan.`);
    }
    const entries = await readdir(current.absolutePath, { withFileTypes: true });
    operation.check();
    const after = await lstat(current.absolutePath, { bigint: false });
    if (!sameStamp(metadataStamp(before), metadataStamp(after))) {
      throw operationError("MCP_WORKSPACE_CHANGED", `Directory ${relativeDirectory || "."} changed during the scan.`);
    }
    const entrySignature = entries
      .map((entry) => `${entry.name}\u0000${entryKind(entry)}`)
      .sort((left, right) => left.localeCompare(right));
    directorySnapshots.push({
      absolutePath: current.absolutePath,
      relativePath: relativeDirectory,
      stamp: metadataStamp(after),
      entries: entrySignature,
    });

    entries.sort((left, right) => left.name.localeCompare(right.name));
    for (const entry of entries) {
      visitedEntries += 1;
      if (visitedEntries > maxEntries) {
        if (allowPartial) {
          truncated ??= "entries";
          walkComplete = false;
          break walk;
        }
        throw operationError("MCP_ENTRY_LIMIT", `Workspace scan exceeded ${maxEntries} entries.`);
      }
      if (entry.isDirectory() && ignored.has(entry.name)) continue;
      const absolutePath = path.join(current.absolutePath, entry.name);
      const relativePath = assertRelativePath(root, absolutePath);
      const stats = await lstat(absolutePath, { bigint: false });
      operation.check();
      if (stats.isSymbolicLink()) {
        skipped.push({ path: relativePath, reason: "symbolic link refused" });
        continue;
      }
      if (stats.isDirectory()) {
        if (current.depth + 1 > maxDepth) {
          if (allowPartial) {
            truncated ??= "depth";
            skipped.push({ path: relativePath, reason: `over ${maxDepth} directory levels` });
            continue;
          }
          throw operationError("MCP_DEPTH_LIMIT", `Workspace scan exceeded ${maxDepth} directory levels.`);
        }
        const low = current.low || (current.depth === 0 && LOW_PRIORITY_TOP.has(entry.name));
        (low ? lowQueue : queue).push({ absolutePath, depth: current.depth + 1, low });
        continue;
      }
      const extension = path.extname(entry.name).toLowerCase();
      const isDeliveryHook = [".githooks/pre-commit", ".githooks/pre-push"].includes(relativePath);
      if (!stats.isFile() || (!isDeliveryHook && !extensions.has(extension))) continue;
      eligibleFiles += 1;
      if (files.length >= maxFiles) {
        if (allowPartial) {
          truncated ??= "files";
          continue;
        }
        throw operationError("MCP_FILE_LIMIT", `Workspace scan exceeded ${maxFiles} readable files.`);
      }
      if (stats.size > maxFileBytes) {
        skipped.push({ path: relativePath, reason: `over ${maxFileBytes} byte limit`, size: stats.size });
        continue;
      }

      if (allowPartial && operation.consumedBytes + pendingVerifyBytes + 2 * stats.size + partialReserveBytes > operation.maxAggregateBytes) {
        truncated ??= "bytes";
        continue;
      }
      const bytes = await readOpenRegularFile(absolutePath, stats, operation, relativePath);
      pendingVerifyBytes += bytes.length;
      const digest = sha256(bytes);
      const file = {
        path: relativePath,
        extension,
        category: categoryFor(relativePath, extension),
        size: bytes.length,
        sha256: digest,
      };
      if (extension === ".json") {
        try {
          const parsed = JSON.parse(bytes.toString("utf8"));
          if (parsed && typeof parsed === "object" && parsed.schemaVersion && parsed.planId && Array.isArray(parsed.tasks)) {
            file.category = "plan";
            file.planId = String(parsed.planId);
            file.taskCount = parsed.tasks.length;
          }
        } catch {
          file.parseWarning = "invalid JSON";
        }
      }
      files.push(file);
      fileSnapshots.push({ absolutePath, relativePath, stamp: metadataStamp(stats), digest });
      if (contentByPath) contentByPath.set(relativePath, bytes);
      await operation.progress({ phase: "scan", path: relativePath, fileCount: files.length });
    }
  }

  // Re-read every accepted file and re-list every directory before returning.
  // The second content hash catches changes even when a timestamp is restored.
  for (const snapshot of fileSnapshots) {
    operation.check();
    const stats = await lstat(snapshot.absolutePath, { bigint: false });
    if (stats.isSymbolicLink() || !stats.isFile() || !sameStamp(snapshot.stamp, metadataStamp(stats))) {
      throw operationError("MCP_WORKSPACE_CHANGED", `File ${snapshot.relativePath} changed during the scan.`);
    }
    const bytes = await readOpenRegularFile(snapshot.absolutePath, stats, operation, snapshot.relativePath);
    if (sha256(bytes) !== snapshot.digest) {
      throw operationError("MCP_WORKSPACE_CHANGED", `File ${snapshot.relativePath} changed during the scan.`);
    }
  }
  for (const snapshot of directorySnapshots) {
    operation.check();
    const stats = await lstat(snapshot.absolutePath, { bigint: false });
    if (stats.isSymbolicLink() || !stats.isDirectory() || !sameStamp(snapshot.stamp, metadataStamp(stats))) {
      throw operationError("MCP_WORKSPACE_CHANGED", `Directory ${snapshot.relativePath || "."} changed during the scan.`);
    }
    const entries = await directoryEntries(snapshot.absolutePath, operation);
    if (!sameEntries(snapshot.entries, entries)) {
      throw operationError("MCP_WORKSPACE_CHANGED", `Directory ${snapshot.relativePath || "."} changed during the scan.`);
    }
  }
  const finalRootRealPath = await realpath(root);
  const finalRootStats = await lstat(root, { bigint: false });
  if (rootRealPath !== finalRootRealPath || !sameStamp(metadataStamp(rootStats), metadataStamp(finalRootStats))) {
    throw operationError("MCP_WORKSPACE_CHANGED", "Registered workspace root changed during the scan.");
  }

  files.sort((left, right) => left.path.localeCompare(right.path));
  skipped.sort((left, right) => left.path.localeCompare(right.path));
  const summary = files.reduce((counts, file) => {
    counts[file.category] = (counts[file.category] ?? 0) + 1;
    return counts;
  }, {});
  const census = Object.freeze({
    schemaVersion: 1,
    root,
    generatedAt: new Date().toISOString(),
    fileCount: files.length,
    totalBytesHashed: files.reduce((total, file) => total + file.size, 0),
    scope: Object.freeze({ excludedDirectoryNames: Object.freeze([...ignored].sort()), includedExtensions: Object.freeze([...extensions].sort()), includedExtensionlessPaths: Object.freeze([".githooks/pre-commit", ".githooks/pre-push"]), malwareAssessed: false }),
    summary: Object.freeze(summary),
    files: Object.freeze(files.map((file) => Object.freeze(file))),
    skipped: Object.freeze(skipped.map((item) => Object.freeze(item))),
    digest: sha256(Buffer.from(files.map((file) => `${file.path}:${file.sha256}`).join("\n"))),
    partial: truncated ? partialNotice(truncated, files.length, eligibleFiles, walkComplete, { maxFiles, maxEntries, maxDirectories, maxDepth, bytes: operation.maxAggregateBytes }) : null,
  });
  return Object.freeze({ census, contentByPath, scannedDirectories: directorySnapshots.length, visitedEntries });
}
